<?php require 'header.php'; master_admin_required(); $db=db_load(); if($_SERVER['REQUEST_METHOD']==='POST'){foreach(['clinic_name','tagline','doctor_name','qualification','phone','email','address','hero_title','hero_text','primary_color','light_color','medium_color','admin_user','admin_password'] as $k)$db['settings'][$k]=trim(post($k));db_save($db);$saved=true;} $s=$db['settings']; ?><div class="admin-top"><h1>Website Settings</h1></div><?php if(!empty($saved)): ?><div class="notice">Settings saved successfully.</div><?php endif; ?><div class="form-card"><form method="post"><div class="form-grid"><?php foreach(['clinic_name'=>'Clinic Name','tagline'=>'Tagline','doctor_name'=>'Doctor Name','qualification'=>'Qualification','phone'=>'Phone','email'=>'Email','address'=>'Address','hero_title'=>'Hero Title','hero_text'=>'Hero Text','primary_color'=>'Dark Green / Primary Color','light_color'=>'Light Green Color','medium_color'=>'Medium Green Color','admin_user'=>'Admin Username','admin_password'=>'Admin Password'] as $k=>$label): ?><div class="field <?=$k==='address'||$k==='hero_title'||$k==='hero_text'?'full':''?>"><label><?=e($label)?></label><?php if ($k === 'admin_password'): ?><div class="password-toggle-wrap"><input id="settingsAdminPassword" type="password" name="<?=e($k)?>" value="<?=e($s[$k])?>"><button type="button" class="password-toggle-btn" data-target="settingsAdminPassword" aria-label="Show password">👁</button></div><?php else: ?><input name="<?=e($k)?>" value="<?=e($s[$k])?>"><?php endif; ?></div><?php endforeach; ?><div class="field full"><button class="btn">Save Settings</button></div></div></form></div><style>.password-toggle-wrap{position:relative}.password-toggle-wrap input{width:100%;padding-right:42px}.password-toggle-btn{position:absolute;right:10px;top:50%;transform:translateY(-50%);border:0;background:transparent;cursor:pointer;font-size:18px;line-height:1;color:#555;padding:4px 6px}</style><script>document.querySelectorAll('.password-toggle-btn').forEach(function(button){button.addEventListener('click',function(){const input=document.getElementById(this.dataset.target);if(!input)return;const isPassword=input.type==='password';input.type=isPassword?'text':'password';this.textContent=isPassword?'🙈':'👁';this.setAttribute('aria-label',isPassword?'Hide password':'Show password');});});</script><?php require 'footer.php'; ?>
